11: /// Singleton service for Google's Gemma AI model - optimized for performance and memory efficiency
12: /// Handles model loading, chat sessions, and streaming responses with minimal overhead
13: class GemmaService {
14:   GemmaService._internal();
15:   static final GemmaService instance = GemmaService._internal();
16: 
17:   final _gemma = FlutterGemmaPlugin.instance;
18:   InferenceModel? _model;
19:   InferenceChat? _chat;
20:   bool _initialised = false;
21: 
22:   /// Initialize model with selected backend (CPU/GPU) - idempotent operation
23:   /// Uses local model file if available to avoid redundant downloads
24:   Future<void> init(PreferredBackend backend) async {
25:     if (_initialised) return; // Prevent duplicate initialization
26: 
27:     final dir = await getApplicationDocumentsDirectory();
28:     final path = '${dir.path}/gemma-3n-E2B-it-int4.task';
29: 
30:     // Point plugin to local model file if it exists and plugin hasn't loaded one yet
31:     if (!await _gemma.modelManager.isModelInstalled &&
32:         File(path).existsSync()) {
33:       await _gemma.modelManager.setModelPath(path);
34:     }
35: 
36:     // Create model instance with vision support and performance settings
37:     _model ??= await _gemma.createModel(
38:       preferredBackend: backend,
39:       modelType: ModelType.gemmaIt, // Instruction-tuned variant
40:       supportImage: true, // Enable vision capabilities
41:       maxTokens: 8192, // Context window size
42:       maxNumImages: 1, // Single image per message
43:     );
44: 
45:     // Create persistent chat session with optimized parameters
46:     _chat ??= await _model!.createChat(
47:       randomSeed: 1, // Deterministic for testing
48:       temperature: 1, // Balanced creativity vs consistency
49:       topK: 64, // Token sampling diversity
50:       topP: 0.95, // Nucleus sampling threshold
51:       supportImage: true,
52:       tokenBuffer: 512, // Reserve tokens for system prompts
53:     );
54: 
55:     _initialised = true;
56:   }
57: 
58:   /// Provides detailed performance statistics and error handling
59:   Future<void> sendWithStreaming({
60:     required String text,
61:     File? image,
62:     required Function(String) onToken,
63:     required Function(MessageStats) onComplete,
64:   }) async {
65:     if (!_initialised) {
66:       throw Exception('GemmaService not initialized');
67:     }
68:     if (_chat == null) {
69:       throw Exception('Chat not available');
70:     }
71: 
72:     // Performance tracking variables
73:     final startTime = DateTime.now();
74:     DateTime? firstTokenTime;
75:     int tokenCount = 0;
76:     final responseBuffer = StringBuffer();
77: 
78:     // Add user message with optional image to chat history
79:     if (image != null) {
80:       final bytes = await image.readAsBytes();
81:       await _chat!.addQuery(
82:         Message.withImage(text: text, imageBytes: bytes, isUser: true),
83:       );
84:     } else {
85:       await _chat!.addQuery(Message.text(text: text, isUser: true));
86:     }
87: 
88:     final completer = Completer<void>();
89:     bool streamStarted = false;
90: 
91:     // Process streaming response with performance metrics
92:     _chat!.generateChatResponseAsync().listen(
93:       (ModelResponse res) {
94:         if (!streamStarted) {
95:           streamStarted = true;
96:         }
97: 
98:         if (res is TextResponse) {
99:           // Record timing for first token (important latency metric)
100:           firstTokenTime ??= DateTime.now();
101:           tokenCount++;
102:           responseBuffer.write(res.token);
103: 
104:           // Forward token to caller (swallow any callback errors)
105:           try {
106:             onToken(res.token);
107:           } catch (_) {
108:             // Ignore callback errors - caller's responsibility
109:           }
110:         }
111:         // Note: Non-text responses (metadata, etc.) are ignored
112:       },
113:       onDone: () {
114:         final endTime = DateTime.now();
115: 
116:         // Calculate comprehensive performance statistics
117:         final stats = MessageStats(
118:           timeToFirstToken: firstTokenTime != null
119:               ? firstTokenTime!.difference(startTime).inMilliseconds / 1000.0
120:               : null,
121:           totalLatency: endTime.difference(startTime).inMilliseconds / 1000.0,
122:           tokenCount: tokenCount,
123:           // Tokens per second during initial processing
124:           prefillSpeed: firstTokenTime != null && tokenCount > 0
125:               ? 1000.0 / firstTokenTime!.difference(startTime).inMilliseconds
126:               : null,
127:           // Tokens per second during generation (excluding first token)
128:           decodeSpeed: firstTokenTime != null && tokenCount > 1
129:               ? (tokenCount - 1) *
130:                     1000.0 /
131:                     endTime.difference(firstTokenTime!).inMilliseconds
132:               : null,
133:         );
134: 
135:         // Deliver final statistics (ignore callback errors)
136:         try {
137:           onComplete(stats);
138:         } catch (_) {
139:           // Silent fallback
140:         }
141: 
142:         completer.complete();
143:       },
144:       onError: (error) {
145:         completer.completeError(error);
146:       },
147:     );
148: 
149:     await completer.future;
150:   }
151: 
152:   /// Fast chat reset - clears conversation history but keeps model loaded in memory
153:   /// Much faster than full reinitialization for "new chat" functionality
154:   Future<void> resetChatSession() async {
155:     if (!_initialised) return;
156:     await _chat?.clearHistory();
157:   }
