160:   /// Use when switching backends or completely shutting down
161:   Future<void> dispose() async {
162:     await _model?.close();
163:     await _gemma.modelManager.deleteModel();
164:     _model = null;
165:     _chat = null;
166:     _initialised = false;
167:   }
